  "severity": "critical",
  "network_observations": [
    {"ip": "10.108.57.184", "inferred_role": "attacker_source_stolen_az_credentials", "first_seen": "2026-05-13T08:02:11+0200", "last_seen": "2026-05-13T08:11:46+0200"}
